using System;
using System.IO;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace SentinelCore.Orchestrations.Infrastructure;

/// <summary>
/// Provides helper methods for formatting the JSON‑based log files generated by <see cref="JsonLoggerProvider" />.
/// It reads a log file that may contain control characters and a stream of consecutive JSON objects,
/// removes non‑printable characters, and writes each entry as indented JSON to a new file.
/// </summary>
public static class LogFileFormatter
{
    // Regex that matches ASCII control characters except whitespace (CR, LF, TAB).
    private static readonly Regex ControlCharsRegex = new("[\x00-\x1F&&[^\r\n\t]]", RegexOptions.Compiled);

    /// <summary>
    /// Formats <paramref name="inputPath"/> and writes a pretty‑printed version to <paramref name="outputPath"/>.
    /// If the file cannot be parsed, the original content is written unchanged.
    /// </summary>
    public static void FormatLogFile(string inputPath, string outputPath)
    {
        if (string.IsNullOrWhiteSpace(inputPath))
            throw new ArgumentException("Input path must be provided.", nameof(inputPath));
        if (string.IsNullOrWhiteSpace(outputPath))
            throw new ArgumentException("Output path must be provided.", nameof(outputPath));

        string rawContent = File.ReadAllText(inputPath, Encoding.UTF8);
        // Remove invisible control characters that interfere with JSON parsing.
        string sanitized = ControlCharsRegex.Replace(rawContent, string.Empty);

        byte[] bytes = Encoding.UTF8.GetBytes(sanitized);
        var options = new JsonReaderOptions { AllowTrailingCommas = true, CommentHandling = JsonCommentHandling.Skip };
        var reader = new Utf8JsonReader(bytes, options);

        using var writer = new StreamWriter(outputPath, false, Encoding.UTF8);
        var prettyOptions = new JsonSerializerOptions { WriteIndented = true };

        try
        {
            while (reader.Read())
            {
                if (reader.TokenType == JsonTokenType.StartObject)
                {
                    using JsonDocument doc = JsonDocument.ParseValue(ref reader);
                    string pretty = JsonSerializer.Serialize(doc.RootElement, prettyOptions);
                    writer.WriteLine(pretty);
                    writer.WriteLine(); // Separate entries for readability.
                }
            }
        }
        catch (JsonException)
        {
            // If parsing fails, fall back to writing the sanitized raw content.
            writer.Write(sanitized);
        }
    }
}
